def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_dedupe_sessions_keeps_last_duplicate_id():
    events = [
        {"id": "x", "day": 1, "converted": True},
        {"id": "y", "day": 2, "converted": False},
        {"id": "x", "day": 3, "converted": False},
    ]
    assert dedupe_sessions(events) == [events[1], events[2]]


def test_conversion_rate_empty_and_none_values():
    assert conversion_rate([]) == 0.0
    assert conversion_rate([{"converted": None}, {"converted": False}]) == 0.0


def test_pooled_conversion_rate_is_weighted_and_empty_safe():
    groups = {
        "large": [{"converted": True}] + [{"converted": False}] * 9,
        "small": [{"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.2
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window_uses_last_days_entries():
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2], 5) == 3


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    assert parse_session_log([
        "  # comment",
        "  ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("lines", [
    ["# skip", "a,not-a-day,1"],
    ["a,1,1,extra"],
    ["a,1"],
])
def test_parse_session_log_errors_include_original_line_number(lines):
    with pytest.raises(ValueError, match="line 2" if lines[0] == "# skip" else "line 1"):
        parse_session_log(lines)


def test_parse_session_log_rejects_unknown_conversion_flag():
    with pytest.raises(ValueError, match="line 1"):
        parse_session_log(["a,1,true"])


def test_daily_conversion_counts_inclusive_range():
    events = [
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": False},
        {"day": 3, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [1, 0, 1]
    assert daily_conversion_counts(events, 4, 2) == []


def test_campaign_summary_rounds_rate_and_counts_nonempty_groups():
