        "a": [{"id": "1", "day": 1, "converted": True}],
        "b": [{"id": "2", "day": 2, "converted": False}],
        "empty": [],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 2}


def test_group_rankings_and_conversion_rates_follow_spec():
    groups = {
        "z": [{"converted": True}],
        "b": [{"converted": False}],
        "a": [{"converted": True}],
        "empty": [],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
